$ErrorActionPreference='Stop'
function A([bool]$ok,[string]$m){if(-not $ok){throw $m}}
function Godot([string]$app){$r=Join-Path $app 'toolchains\godot';$g=Get-ChildItem $r -Filter '*_console.exe' -File -ErrorAction SilentlyContinue|Select-Object -First 1;if(-not $g){$g=Get-ChildItem $r -Filter 'Godot_v4*.exe' -File -ErrorAction SilentlyContinue|Where-Object{$_.Name-notmatch'_console\.exe$'}|Select-Object -First 1};if(-not $g){throw'Bundled Godot missing'};return $g.FullName}
