node --check (Join-Path $app 'public\forge-runtime-guard.js');node --check $sPath;node --check $aPath;A ((Get-Content $sPath -Raw)-notmatch'setInterval\(render') 'Idle loop remains';A ((Get-Content $agentPath -Raw)-notmatch'isRun \|\| customGodotValidation') 'Duplicate import remains';A ((Get-Content (Join-Path $app 'public\forge-runtime-guard.js') -Raw)-match'Del ZIP al proyecto listo para probar') 'UX purpose missing';Smoke $g 'patched';"PATCHED=$patched">>$env:GITHUB_ENV;"BASE_INSTALL=$inst">>$env:GITHUB_ENV;Write-Host 'FORGE_0383_PREPARED_OK'
